#if VERIFY
startingSeat=VerificationRun.FirstSeat;
#endif
lanAuthority=new LanHostGame(catalog,lanChosenDeck,guest,Environment.TickCount,startingSeat,lanChosenName,message.PlayerName);lanAuthority.SetPresentation(0,CurrentEffects);lanAuthority.SetPresentation(1,message.ReadEffects());match=lanAuthority.Game;lanSession=lanAuthority.Session;lanRevision=0;lanReady=true;matchViewSeat=0;awaitHandoff=false;ClearPending();inspectMatch=false;matchHandScroll=0;PublishLan();RenderMatch();ShowPage("match");status.Text="局域网已连接 · "+(match.FirstSeat==matchViewSeat?"我方先手":"我方后手");return;}
    if(message.Kind=="arena-pick"&&lanArenaDraft!=null&&!lanReady){try{lanArenaDraft.Pick(1,message.ArenaSession,message.ArenaRevision,message.ChoiceIndex);}catch(InvalidOperationException ex){lanPeer.Send(new LanMessage{Kind="arena-draft",ArenaDraft=lanArenaDraft.View(1),Message=ex.Message});return;}lanArenaView=lanArenaDraft.View(0);UpdateArenaDraftUi(lanArenaView);if(lanArenaDraft.View(0).Complete&&lanArenaDraft.View(1).Complete){StartArenaMatch();return;}PublishArenaDraftToGuest();return;}
    if(message.Kind=="log-ack"&&lanReady){lanAuthority.AcknowledgeLog(message.LogSession,message.LogAck);return;}
    if(message.Kind=="presentation"&&lanSealedMode&&!lanReady){lanGuestEffects=message.ReadEffects();return;}if(message.Kind=="presentation"&&lanArenaDraft!=null&&!lanReady){lanGuestEffects=message.ReadEffects();return;}if(message.Kind=="presentation"&&lanReady){lanAuthority.SetPresentation(1,message.ReadEffects());return;}
    if(message.Kind=="command"&&lanReady){int beforeExecuteRevision=lanAuthority.Revision;var result=lanAuthority.Execute(1,message.Command);lanRevision=lanAuthority.Revision;bool presentationOnly=message.Command!=null&&message.Command.Kind=="emote";PublishLan(result,message.Command==null?0:message.Command.RequestId,presentationOnly);if(result.Success||lanAuthority.Revision!=beforeExecuteRevision){if(!presentationOnly){ClearPending();inspectMatch=false;}RenderMatch();}return;}
    throw new InvalidDataException("房间收到无效消息。");
