 void PublishLan(ActionResult result=null,int replyId=0,bool presentationOnly=false){if(lanAuthority!=null&&match!=lanAuthority.Game){match=lanAuthority.Game;matchViewSeat=0;selectedMulligan.Clear();ClearPending();inspectMatch=testTakeOpen=emoteOpen=false;matchHandScroll=0;awaitHandoff=false;RenderMatch();}var outgoing=lanAuthority.Snapshot(result,replyId,presentationOnly);StampSealed(outgoing);if(lanPeer==null||!lanPeer.Send(outgoing))DisconnectLan("发送失败。");}
 bool CanMulliganInput(){if(match==null||match.Finished||match.MulliganComplete||matchViewSeat<0||matchViewSeat>1||match.Players[matchViewSeat].MulliganDone||agentMatch&&matchViewSeat!=0)return false;if(lanMode)return lanReady&&!lanWaiting&&lanPeer!=null;return !awaitHandoff;}
 bool CanMatchAction(string kind){return kind=="mulligan"?CanMulliganInput():CanMatchInput();}
 bool CanMatchInput(){if(agentMatch&&matchViewSeat!=0)return false;if(match==null||match.Finished||awaitHandoff||match.AnimationPlaying||match.TurnClockExpired)return false;if(lanMode&&!lanReady||lanWaiting)return false;if(!match.MulliganComplete)return !match.Players[matchViewSeat].MulliganDone;return !(lanMode||agentMatch)||match.Active==matchViewSeat;}
 void DoMatch(string kind,int source=0,MatchTarget target=null,int position=-1,string choice=null,int[] selectedIds=null,string emote=null){
  if(agentMatch&&kind!="emote"&&!CanMatchAction(kind)){status.Text="等待"+AgentName()+"操作。";return;}
  if(kind=="emote"&&minimal){status.Text="极简模式已禁用对话。";return;}
  if(lanMode){bool mayEmote=kind=="emote"&&match!=null&&match.MulliganComplete&&!match.AnimationPlaying&&!match.Finished&&lanReady&&!lanWaiting;if(!CanMatchAction(kind)&&!mayEmote){status.Text=match!=null&&match.AnimationPlaying?"正在播放动画，请稍候。":!lanReady?"连接已断开，请重新建房。":lanWaiting?"等待同步。":"等待对方操作。";return;}var command=new LanCommand{Kind=kind,Source=source,Target=target,Position=position,Choice=choice,SelectedHandIds=selectedIds,Emote=emote,Session=lanSession,Revision=lanRevision,RequestId=++lanRequestId};if(lanIsHost){int beforeExecuteRevision=lanAuthority.Revision;var result=lanAuthority.Execute(0,command);lanRevision=lanAuthority.Revision;PublishLan(result,presentationOnly:kind=="emote");if(kind=="emote"&&result.Success){RenderMatch();status.Text=result.Message;}else{ApplyMatchAction(result);if(!result.Success&&lanAuthority.Revision!=beforeExecuteRevision)RenderMatch();}}else{lanWaiting=true;lanPendingRequest=command.RequestId;if(lanPeer==null||!lanPeer.Send(new LanMessage{Kind="command",Command=command})){DisconnectLan("发送失败。");return;}RenderMatch();status.Text="等待同步。";}return;}
  ActionResult local;switch(kind){case "mulligan":local=match.Mulligan(matchViewSeat,selectedIds);if(local.Success&&!agentMatch){handoffSeat=match.MulliganComplete?match.Active:1-matchViewSeat;awaitHandoff=true;}break;case "emote":local=match.Emote(matchViewSeat,emote);break;case "play":local=match.Play(matchViewSeat,source,target,position,choice);break;case "attack":local=match.Attack(matchViewSeat,source,target);break;case "power":local=match.HeroPower(matchViewSeat,target);break;default:local=match.EndTurn();if(local.Success&&!match.Finished&&!agentMatch){handoffSeat=match.Active;awaitHandoff=true;}break;}ApplyMatchAction(local);
 }
 string LanTurnHint(){if(!lanReady)return "连接已断开";if(lanWaiting)return "同步中…";if(lanSealedMode)return lanArenaWins0+" - "+lanArenaWins1+" · 现开赛 · "+(match.Active==matchViewSeat?"我的回合":"对方回合");if(lanArenaMode)return (ArenaSeriesLabel()??"竞技赛")+" · "+(match.Active==matchViewSeat?"我的回合":"对方回合");return match.Active==matchViewSeat?"我的回合":"对方回合";}
